"use client"

import * as React from "react"
import {
  ChevronRight,
  Moon,
  PanelLeftIcon,
  Search,
  Sun,
  SunMoon,
} from "lucide-react"
import type { LucideIcon } from "lucide-react"
import { toast, Toaster } from "sonner"

import { cn } from "@/lib/utils"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarRail,
  useSidebar,
} from "@/components/ui/sidebar"
import {
  useAdminTheme,
  type ThemeChoice,
  type ThemeController,
} from "@/hooks/use-admin-theme"

export type AdminNavItem = {
  href: string
  label: string
  icon: LucideIcon
  description?: string
  count?: number
}

export type AdminNavGroup = {
  label: string
  items: AdminNavItem[]
}

export type AdminCrumb = {
  label: string
  href?: string
}

export type AdminLinkProps = {
  href: string
  className?: string
  children?: React.ReactNode
  title?: string
  onClick?: (event: React.MouseEvent<HTMLAnchorElement>) => void
  "aria-current"?: "page" | undefined
}

export type AdminShellProps = {
  groups: readonly AdminNavGroup[]
  pathname: string
  onNavigate?: (href: string) => void
  linkComponent?: React.ComponentType<AdminLinkProps>
  /** Brand block in the sidebar header. */
  brand?: React.ReactNode
  /** Right side of the top bar, before the theme button. */
  actions?: React.ReactNode
  theme?: ThemeChoice
  resolvedTheme?: "light" | "dark"
  onThemeChange?: (theme: ThemeChoice) => void
  /** next-themes (or any host) controller. Wins over theme/onThemeChange. */
  themeController?: ThemeController
  commandLabel?: string
  emptyCommand?: string
  themeLabel?: string
  /** Names for light, dark, and system in the theme button. */
  themeNames?: Partial<Record<ThemeChoice, string>>
  /** First breadcrumb and the brand fallback. */
  rootLabel?: string
  /** Accessible name of the sidebar toggle. */
  sidebarLabel?: string
  className?: string
  contentClassName?: string
  showToaster?: boolean
  /** pill draws an inverted active item and flips the count chip. */
  navStyle?: "row" | "pill"
  children?: React.ReactNode
}

export function breadcrumbsFor(
  groups: readonly AdminNavGroup[],
  pathname: string,
  rootLabel = "Admin",
): AdminCrumb[] {
  const crumbs: AdminCrumb[] = [{ label: rootLabel, href: groups[0]?.items[0]?.href }]
  for (const group of groups) {
    for (const item of group.items) {
      const exact = pathname === item.href
      const nested = item.href !== "/" && pathname.startsWith(`${item.href}/`)
      if (exact || nested) {
        crumbs.push({ label: item.label, href: item.href })
        return crumbs
      }
    }
  }
  return crumbs
}

function SidebarToggle({ label }: { label: string }) {
  const { toggleSidebar } = useSidebar()
  return (
    <Button
      type="button"
      data-sidebar="trigger"
      data-slot="sidebar-trigger"
      variant="ghost"
      size="icon-sm"
      className="motion-reduce:transition-none"
      onClick={toggleSidebar}
    >
      <PanelLeftIcon />
      <span className="sr-only">{label}</span>
    </Button>
  )
}

function ThemeIcon({ theme }: { theme: ThemeChoice }) {
  if (theme === "dark") return <Moon />
  if (theme === "light") return <Sun />
  return <SunMoon />
}

export function AdminShell({
  groups,
  pathname,
  onNavigate,
  linkComponent,
  brand,
  actions,
  theme,
  resolvedTheme,
  onThemeChange,
  themeController,
  commandLabel = "Search pages",
  emptyCommand = "No pages",
  themeLabel = "Theme",
  themeNames,
  rootLabel = "Admin",
  sidebarLabel = "Toggle sidebar",
  className,
  contentClassName,
  showToaster = true,
  navStyle = "row",
  children,
}: AdminShellProps) {
  const controller = themeController ?? (
    onThemeChange
      ? {
          theme: theme ?? "system",
          setTheme: onThemeChange,
          resolvedTheme,
        }
      : undefined
  )
  const themeState = useAdminTheme(controller)
  const [commandOpen, setCommandOpen] = React.useState(false)
  const crumbs = breadcrumbsFor(groups, pathname, rootLabel)
  const themeName = themeNames?.[themeState.theme] ?? themeState.theme
  const LinkComponent = linkComponent ?? "a"

  React.useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (event.key.toLowerCase() === "k" && (event.metaKey || event.ctrlKey)) {
        event.preventDefault()
        setCommandOpen((open) => !open)
      }
    }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [])

  function go(href: string) {
    setCommandOpen(false)
    if (onNavigate) {
      onNavigate(href)
      return
    }
    const link = document.createElement("a")
    link.href = href
    link.hidden = true
    document.body.appendChild(link)
    link.click()
    link.remove()
  }

  return (
    <SidebarProvider className={cn("min-h-svh bg-background", className)}>
      <Sidebar collapsible="icon" className="border-sidebar-border">
        <SidebarHeader className="border-b border-sidebar-border">
          {brand ?? (
            <div className="px-2 py-1 text-sm font-semibold group-data-[collapsible=icon]:hidden">
              {rootLabel}
            </div>
          )}
        </SidebarHeader>
        <SidebarContent>
          {groups.map((group) => (
            <SidebarGroup key={group.label}>
              <SidebarGroupLabel>{group.label}</SidebarGroupLabel>
              <SidebarGroupContent>
                <SidebarMenu>
                  {group.items.map((item) => {
                    const active = pathname === item.href
                    const Icon = item.icon
                    return (
                      <SidebarMenuItem key={item.href}>
                        <SidebarMenuButton
                          asChild
                          isActive={active}
                          tooltip={item.label}
                          className={navStyle === "pill" ? "rounded-full data-active:bg-foreground data-active:text-background" : undefined}
                        >
                          <LinkComponent
                            href={item.href}
                            aria-current={active ? "page" : undefined}
                            onClick={(event) => {
                              if (onNavigate) {
                                event.preventDefault()
                                go(item.href)
                              }
                            }}
                          >
                            <Icon />
                            <span>{item.label}</span>
                            {item.count != null ? (
                              <span
                                className={cn(
                                  "ms-auto rounded-full px-1.5 text-xs tabular-nums",
                                  active && navStyle === "pill" ? "bg-primary text-primary-foreground" : "bg-sidebar-accent text-sidebar-foreground",
                                )}
                              >
                                {item.count}
                              </span>
                            ) : null}
                          </LinkComponent>
                        </SidebarMenuButton>
                      </SidebarMenuItem>
                    )
                  })}
                </SidebarMenu>
              </SidebarGroupContent>
            </SidebarGroup>
          ))}
        </SidebarContent>
        <SidebarRail aria-label={sidebarLabel} title={sidebarLabel} />
      </Sidebar>
      <SidebarInset className="min-w-0 bg-background">
        <header className="sticky top-0 z-20 flex h-14 items-center gap-2 border-b border-border bg-background/95 px-3 backdrop-blur-sm motion-reduce:backdrop-blur-none">
          <SidebarToggle label={sidebarLabel} />
          <Breadcrumb>
            <BreadcrumbList>
              {crumbs.map((crumb, index) => {
                const last = index === crumbs.length - 1
                return (
                  <React.Fragment key={`${crumb.label}-${index}`}>
                    {index > 0 ? (
                      <BreadcrumbSeparator>
                        <ChevronRight />
                      </BreadcrumbSeparator>
                    ) : null}
                    <BreadcrumbItem>
                      {last || !crumb.href ? (
                        <BreadcrumbPage>{crumb.label}</BreadcrumbPage>
                      ) : (
                        <BreadcrumbLink asChild>
                          <LinkComponent
                            href={crumb.href}
                            onClick={(event) => {
                              if (onNavigate && crumb.href) {
                                event.preventDefault()
                                go(crumb.href)
                              }
                            }}
                          >
                            {crumb.label}
                          </LinkComponent>
                        </BreadcrumbLink>
                      )}
                    </BreadcrumbItem>
                  </React.Fragment>
                )
              })}
            </BreadcrumbList>
          </Breadcrumb>
          <div className="ml-auto flex items-center gap-1">
            <Button
              type="button"
              variant="outline"
              size="sm"
              className="hidden sm:inline-flex"
              onClick={() => setCommandOpen(true)}
            >
              <Search />
              {commandLabel}
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="sm:hidden"
              aria-label={commandLabel}
              onClick={() => setCommandOpen(true)}
            >
              <Search />
            </Button>
            {actions}
            <Button
              type="button"
              variant="ghost"
              size="icon"
              aria-label={`${themeLabel}: ${themeName}`}
              onClick={themeState.cycle}
            >
              <ThemeIcon theme={themeState.theme} />
            </Button>
          </div>
        </header>
        <div className={cn("flex min-w-0 flex-1 flex-col gap-4 p-4 md:p-6", contentClassName)}>
          {children}
        </div>
      </SidebarInset>
      <CommandDialog
        open={commandOpen}
        onOpenChange={setCommandOpen}
        title={commandLabel}
        description={commandLabel}
      >
        <CommandInput placeholder={commandLabel} />
        <CommandList>
          <CommandEmpty>{emptyCommand}</CommandEmpty>
          {groups.map((group) => (
            <CommandGroup key={group.label} heading={group.label}>
              {group.items.map((item) => {
                const Icon = item.icon
                return (
                  <CommandItem
                    key={item.href}
                    value={`${item.label} ${item.description ?? ""}`}
                    onSelect={() => go(item.href)}
                  >
                    <Icon />
                    <span>{item.label}</span>
                  </CommandItem>
                )
              })}
            </CommandGroup>
          ))}
        </CommandList>
      </CommandDialog>
      {showToaster ? (
        <Toaster
          theme={themeState.resolvedTheme}
          richColors
          closeButton
        />
      ) : null}
    </SidebarProvider>
  )
}

export { toast as adminToast }

"use client"

import * as React from "react"

export type ThemeChoice = "light" | "dark" | "system"

export type ThemeController = {
  theme: ThemeChoice
  setTheme: (theme: ThemeChoice) => void
  resolvedTheme?: "light" | "dark"
}

const ORDER: ThemeChoice[] = ["light", "dark", "system"]
const listeners = new Set<() => void>()

function readStored(): ThemeChoice {
  try {
    const stored = window.localStorage.getItem("theme")
    if (stored === "light" || stored === "dark" || stored === "system") return stored
  } catch {
    /* private mode */
  }
  return "system"
}

function emit() {
  for (const listener of listeners) listener()
}

function subscribe(onStoreChange: () => void) {
  listeners.add(onStoreChange)
  const media = window.matchMedia("(prefers-color-scheme: dark)")
  media.addEventListener("change", onStoreChange)
  return () => {
    listeners.delete(onStoreChange)
    media.removeEventListener("change", onStoreChange)
  }
}

function systemPrefersDark() {
  return window.matchMedia("(prefers-color-scheme: dark)").matches
}

function applyClass(choice: ThemeChoice) {
  const dark = choice === "dark" || (choice === "system" && systemPrefersDark())
  document.documentElement.classList.toggle("dark", dark)
  return dark ? "dark" : "light"
}

/**
 * Theme hook-in.
 *
 * Pass the host's next-themes controller (`{ theme, setTheme, resolvedTheme }`)
 * when the app already has one. With no controller, this toggles the `dark`
 * class on `<html>` and stores the choice under `localStorage.theme`.
 */
export function useAdminTheme(controller?: ThemeController) {
  const stored = React.useSyncExternalStore(subscribe, readStored, () => "system" as const)
  const systemDark = React.useSyncExternalStore(subscribe, systemPrefersDark, () => false)
  const localResolved = stored === "dark" || (stored === "system" && systemDark) ? "dark" : "light"

  React.useEffect(() => {
    if (controller) return
    applyClass(stored)
  }, [controller, stored])

  const theme = controller?.theme ?? stored
  const resolvedTheme = controller?.resolvedTheme ?? localResolved

  const setTheme = React.useCallback(
    (next: ThemeChoice) => {
      if (controller) {
        controller.setTheme(next)
        return
      }
      try {
        window.localStorage.setItem("theme", next)
      } catch {
        /* private mode */
      }
      applyClass(next)
      emit()
    },
    [controller],
  )

  const cycle = React.useCallback(() => {
    const index = ORDER.indexOf(theme)
    const next = ORDER[(index + 1) % ORDER.length] ?? "system"
    setTheme(next)
  }, [setTheme, theme])

  return { theme, resolvedTheme, setTheme, cycle }
}
